"use client";

import { useEffect, useState, useRef } from "react";

export default function MissionStatement() {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef<HTMLDivElement>(null);

  const missionText = "Our software powers real-time, AI-driven decisions in critical institutional and commercial grids in the West, from the facility floors to the front lines.";
  const words = missionText.split(" ");

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect(); 
        }
      },
      // Lowered threshold to 10% to ensure it triggers perfectly on all network screen sizes
      { threshold: 0.1 } 
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  return (
    <section className="w-full bg-white text-zinc-900 font-sans border-b border-zinc-200 flex flex-col justify-between overflow-hidden">
      
      <div className="flex-grow flex items-center justify-center py-32 md:py-48 px-4 md:px-8 min-h-[70vh]">
        <div ref={sectionRef} className="max-w-[1400px] w-full text-center">
          <h2 
            className="font-medium text-[#161616] leading-[1.05] flex flex-wrap justify-center"
            style={{ fontSize: "clamp(2rem, 5vw, 5.5rem)" }}
          >
            {words.map((word, i) => (
              <span
                key={i}
                className={`inline-block transition-all duration-1000 ease-out ${
                  isVisible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-6"
                }`}
                // Slower typing speed: 400ms delay per word (Total ~9 seconds)
                style={{ transitionDelay: `${i * 400}ms` }} 
              >
                {word === "AI-driven" ? (
                  <span className="text-zinc-500">{word}</span>
                ) : (
                  word
                )}
                &nbsp;
              </span>
            ))}
          </h2>
        </div>
      </div>

      <div className="w-full px-8 pb-16 max-w-[1400px] mx-auto bg-white">
        <h3 
          className="font-normal text-[#161616] transition-all duration-1000 ease-out"
          style={{ 
            fontSize: "clamp(2.5rem, 5vw, 4rem)", 
            letterSpacing: "-0.02em",
            opacity: isVisible ? 1 : 0,
            transform: isVisible ? "translateY(0)" : "translateY(20px)",
            // "Our Software" fades in immediately after the last word finishes typing
            transitionDelay: `${words.length * 400 + 400}ms` 
          }}
        >
          Our Software
        </h3>
      </div>
    </section>
  );
}